        getPerformanceSummary(history) {
            if (!history.length) return {};
            var last = history[history.length - 1];
            var ds = last.results || {};

            var pmfPoints = Math.min(300, Math.round((ds.pmf || 0) * 3));
            var runwayPoints = 0;
            if ((ds.runway || 0) >= 52) runwayPoints = 250;
            else if ((ds.runway || 0) >= 26) runwayPoints = 180;
            else if ((ds.runway || 0) >= 12) runwayPoints = 100;
            else runwayPoints = Math.round((ds.runway || 0) * 4);

            var ltvCacPoints = 0;
            var ratio = ds.ltvCac || 0;
            if (ratio >= 5) ltvCacPoints = 200;
            else if (ratio >= 3) ltvCacPoints = 150;
            else if (ratio >= 1) ltvCacPoints = 80;
            else ltvCacPoints = Math.round(ratio * 40);

            var improvementCount = 0;
            for (var i = 1; i < history.length; i++) {
                var prev = history[i - 1].results || {};
                var curr = history[i].results || {};
                if ((curr.revenue || 0) > (prev.revenue || 0)) improvementCount++;
                if ((curr.pmf || 0) > (prev.pmf || 0)) improvementCount++;
            }
            var learningPoints = Math.min(150, improvementCount * 25);

            var teamPoints = Math.min(100, Math.round((ds.teamHealth || 0)));

            var totalScore = pmfPoints + runwayPoints + ltvCacPoints + learningPoints + teamPoints;

            // Insolvency gate: a venture that ran cash to zero/negative or hit 0 runway is NOT
            // ”sustainable”, whatever the vanity metrics say (core Runway-Meter pedagogy).
            var insolvent = false;
            for (var hi = 0; hi < history.length; hi++) {
                var rr = history[hi].results || {};
                if ((typeof rr.cash === 'number' && rr.cash < 0) || rr.runway === 0) { insolvent = true; break; }
            }

            var performance;
            if (insolvent) performance = this._t('perf_insolvent', 'Insolvent — Ran Out of Runway');
            else if (totalScore >= 800) performance = this._t('perf_excellent', 'Excellent — Unicorn Potential');
            else if (totalScore >= 600) performance = this._t('perf_good', 'Good — Sustainable Venture');
            else if (totalScore >= 400) performance = this._t('perf_average', 'Average — Survival Mode');
            else performance = this._t('perf_needs', 'Needs Improvement');

            var insights = [];
            if (insolvent) {
                insights.push(this._t('insight_insolvent', 'The venture ran out of runway (cash reached zero). In a startup, running out of money ends the game — protect runway before chasing growth.'));
            }
            if (pmfPoints >= 200) {
                insights.push(this._t('insight_pmf_strong', 'Strong product-market fit achieved — your customers love the product.'));
            } else {
                insights.push(this._t('insight_pmf_weak', 'Product-market fit needs more iteration — revisit your value proposition.'));
            }
            if (ratio >= 3) {
                insights.push(this._t('insight_ltvcac_good', 'Healthy unit economics — your LTV/CAC ratio supports scaling.'));
            } else {
                insights.push(this._t('insight_ltvcac_bad', 'Unit economics need improvement — customer acquisition is too expensive relative to lifetime value.'));
            }
            if ((ds.teamHealth || 0) >= 70) {
                insights.push(this._t('insight_team_strong', 'Team cohesion is strong — a solid foundation for growth.'));
            } else {
                insights.push(this._t('insight_team_weak', 'Team health is a concern — co-founder alignment is critical for long-term success.'));
            }

            return {
                totalScore: totalScore,
                performance: performance,
                insolvent: insolvent,
                pmfPoints: pmfPoints,
                financialPoints: runwayPoints,
                ltvCacPoints: ltvCacPoints,
                learningPoints: learningPoints,
                teamPoints: teamPoints,
                insights: insights
            };
        }

        getHint(state, results) {
            if (state.domainState.cash <= 0 || state.domainState.runwayWeeks <= 0) {
                return window.mySimulation.t('hint_insolvent');
            }
            if (state.domainState.runwayWeeks < 12) {
                return window.mySimulation.t('hint_low_runway');
            }
            if (state.domainState.monthlyBurn > state.domainState.monthlyRevenue * 2) {
                return window.mySimulation.t('hint_high_burn');
            }
            if (state.domainState.ltvCacRatio >= 3 && state.domainState.pmfScore >= 40) {
                return window.mySimulation.t('hint_good_metrics');
            }
            if (state.domainState.pmfScore < 30) {
                return window.mySimulation.t('hint_low_pmf');
            }
            if (state.currentPeriod === 3 && state.domainState.momGrowth < 35) {
                return window.mySimulation.t('hint_growth_target');
            }
            return null;
        }

